// Auth store (generated by engineering-platform frontend-auth asset)
// Minimal V1: token + currentUser + authenticated. Business data stays out.
import { defineStore } from 'pinia';
import { authApi } from '../api/auth';
import type { CurrentUser } from '../types/auth';

const TOKEN_KEY = 'ep.token';
const CURRENT_USER_KEY = 'ep.currentUser';

interface AuthState {
  token: string | null;
  currentUser: CurrentUser | null;
}

export const useAuthStore = defineStore('auth', {
  state: (): AuthState => ({
    token: localStorage.getItem(TOKEN_KEY),
    currentUser: readStoredUser(),
  }),
  getters: {
    authenticated: (state): boolean => !!state.token,
    permissions: (state): string[] => state.currentUser?.permissions ?? [],
  },
  actions: {
    async login(username: string, password: string): Promise<void> {
      const response = await authApi.login({ username, password });
      this.token = response.token;
      localStorage.setItem(TOKEN_KEY, response.token);
      await this.loadCurrentUser();
    },
    async loadCurrentUser(): Promise<void> {
      const user = await authApi.me();
      this.currentUser = user;
      localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    },
    logout(): void {
      this.token = null;
      this.currentUser = null;
      localStorage.removeItem(TOKEN_KEY);
      localStorage.removeItem(CURRENT_USER_KEY);
    },
  },
});

function readStoredUser(): CurrentUser | null {
  const raw = localStorage.getItem(CURRENT_USER_KEY);
  if (!raw) {
    return null;
  }
  try {
    return JSON.parse(raw) as CurrentUser;
  } catch {
    return null;
  }
}
